p='crates/rich-editor-auy/tests/alloc.rs'
s=open(p).read()
old = """    // Chunked storage deliberately trades a few small directory allocations for O(chunk)
    // copying instead of O(document) copying.
    assert!(
        allocations() <= 40,
        "hot-path insert allocated {} times",
        allocations()
    );"""
new = """    // Calibrated ceiling for one-character insert into a one-block document. The remaining
    // sites, smallest stable set: the replacement `String`, the `Vec<InlineItem>`, the
    // `TextBlock`, the `Arc<Block>`, the `ChangeSet` range slice, the `Step` vector and the
    // `inverse` vector, the chunk slot for the replaced block, the `DocInner` `Arc`, the
    // `Group` with its copied step vector, and the cloned history stack. Reaching zero would
    // need an arena or `unsafe`, both forbidden in the core.
    assert!(
        allocations() <= 16,
        "hot-path insert allocated {} times",
        allocations()
    );"""
assert old in s
s = s.replace(old, new)
old2 = """    assert!(
        allocations() <= 30,
        "owned hot-path insert allocated {} times",
        allocations()
    );"""
new2 = """    // The owned path drops the history-stack clone and the `Doc` snapshot copy, so it stays
    // strictly below `one_character_insertion_has_a_bounded_allocation_count`.
    assert!(
        allocations() <= 11,
        "owned hot-path insert allocated {} times",
        allocations()
    );"""
assert old2 in s
s = s.replace(old2, new2)
open(p,'w').write(s)
EOF
