        &mut self,
        bytes: u64,
        limits: &Limits,
        offset: u32,
        path: &[u32],
    ) -> Result<(), ParseError> {
        if bytes > u64::from(limits.max_block_text_bytes) {
            return Err(limit_error(offset, path));
        }
        self.text_bytes = self.text_bytes.saturating_add(bytes);
        if self.text_bytes > u64::from(limits.max_doc_bytes) {
            return Err(limit_error(offset, path));
        }
        Ok(())
    }
