    pub fn child(&self, index: u32) -> Self {
        // Decimal digits are written by hand: `format!` allocates a second buffer per node,
        // and the a11y tree builds one path per block.
        let mut digits = [0_u8; 10];
        let mut cursor = digits.len();
        let mut remaining = index;
        while remaining > 0 {
            cursor = cursor.saturating_sub(1);
            let Some(slot) = digits.get_mut(cursor) else {
                return self.clone();
            };
            *slot = u8::try_from(remaining % 10).unwrap_or(0).saturating_add(b'0');
            remaining /= 10;
        }
        if cursor == digits.len() {
            // `index` is zero: emit a single digit.
            let Some(slot) = digits.last_mut() else {
                return self.clone();
            };
            *slot = b'0';
            cursor = digits.len().saturating_sub(1);
        }
        let separator = if self.0.is_empty() { 0 } else { 1 };
        let width = digits.len().saturating_sub(cursor).saturating_add(separator);
        let mut value = alloc::string::String::with_capacity(self.0.len().saturating_add(width));
        value.push_str(&self.0);
        if separator > 0 {
            value.push('/');
        }
        for digit in digits.get(cursor..).unwrap_or(&[]) {
            value.push(char::from(*digit));
