    let blocks = value.get("blocks").ok_or_else(|| ParseError {
        code: Box::from("missing_blocks"),
        offset: value.start(),
        path: Box::from("blocks"),
    })?;
    let values = blocks.as_array().ok_or_else(|| ParseError {
        code: Box::from("blocks_not_array"),
        offset: blocks.start(),
        path: Box::from("blocks"),
    })?;
