    let decoded = decode_blocks(values, schema, options)?;
    let doc = check_doc(
        Doc::from_decoded(Attrs::empty(), decoded),
        schema,
        value.start(),
    )?;
    Ok(Fragment::new(doc.blocks().to_vec()))
