//! Editing, mapping, and history smoke tests.

use std::sync::Arc;

use rich_editor_auy::model::{Attrs, Block, Doc, InlineItem, Mark, MarkSet, Run, TextBlock};
use rich_editor_auy::pos::{Pos, Range};
