    pub fn from_steps(old: &Doc, new: &Doc, steps: &[Step], selection_changed: bool) -> Self {
        let mut builder = ChangeBuilder::new();
        for step in steps {
            builder.push(step, old);
        }
        builder.finish(new, selection_changed)
    }

