/// Decodes a JSON object of names into node attributes.
fn node_attrs(
    schema: &Schema,
    kind: NodeKind,
    attrs: Option<String>,
) -> Result<Attrs, JsValue> {
    let mut decoded = Attrs::empty();
    let Some(raw) = attrs else {
        return Ok(decoded);
    };
    let value: Value = serde_json::from_str(&raw)
        .map_err(|error| problem_js(&problem::malformed_problem(format!("{error}"), "attrs")))?;
    let Value::Object(map) = value else {
        return Err(problem_js(&problem::malformed_problem(
            String::from("attrs must be an object"),
            "attrs",
        )));
    };
    for (name, item) in &map {
        let spec = schema
            .node_attr(kind, name)
            .ok_or_else(|| problem_js(&problem::attr_problem(name, "node")))?;
        decoded = with_attr(&decoded, spec, item, name)?;
    }
    Ok(decoded)
}

/// Decodes one attribute value and appends it to a set.
fn with_attr(
    attrs: &Attrs,
    spec: &AttrSpec,
    value: &Value,
    name: &str,
) -> Result<Attrs, JsValue> {
    let decoded = attr::value_from_json(&spec.kind, value, name)
        .map_err(|problem| problem_js(&problem))?;
    attrs
        .with(Attr {
            id: spec.id,
            value: decoded,
        })
        .ok_or_else(|| problem_js(&problem::invalid_attr_problem(name, "node")))
}

