    #[must_use]
    pub fn import(&mut self, payload: &str) -> String {
        let parsed = match serde_json::from_str::<ImportPayload>(payload) {
            Ok(parsed) => parsed,
            Err(error) => {
                let problem = problem::malformed_problem(format!("{error}"), "import");
