    ///
    /// # Errors
    ///
    /// Returns an unsupported error when an open edge does not sit inside a text block, when the
    /// merged edges disagree on the block kind, or when a closed edge is not block-aligned.
    fn replace_open(&self, slice: &Slice, range: Range) -> Result<Self, StepError> {
        check_open_depth(slice)?;
        if range.start >= range.end {
            return Err(open_boundary());
        }
        let from = self.boundary(range.start);
        let to = self.boundary(range.end);
        if slice.open_start > 0 && from.is_some() {
            return Err(open_boundary());
        }
        if slice.open_end > 0 && to.is_some() {
            return Err(open_boundary());
        }
        if slice.open_start == 0 && from.is_none() {
            return Err(StepError::Unsupported {
                operation: Box::from("slice_replace_start_not_aligned"),
            });
        }
        if slice.open_end == 0 && to.is_none() {
            return Err(StepError::Unsupported {
                operation: Box::from("slice_replace_end_not_aligned"),
            });
        }
        let start_edge = if slice.open_start > 0 {
            self.strict_text_at(range.start)?
        } else {
            None
        };
        let end_edge = if slice.open_end > 0 {
            self.strict_text_at(range.end)?
        } else {
            None
        };
        if slice.open_start > 0 && start_edge.is_none() {
            return Err(open_boundary());
        }
        if slice.open_end > 0 && end_edge.is_none() {
            return Err(open_boundary());
        }
        let mut blocks = slice.content.blocks().to_vec();
        if let Some((_, host, local)) = start_edge {
            let text = host.as_textblock().ok_or_else(open_structural)?;
            let prefix = slice_text(text, 0, local)?;
            merge_into(&mut blocks, host, &prefix, true)?;
        }
        if let Some((_, host, local)) = end_edge {
            let text = host.as_textblock().ok_or_else(open_structural)?;
            let length = usize::try_from(text.len().0).unwrap_or(usize::MAX);
            let suffix = slice_text(text, local, length)?;
            merge_into(&mut blocks, host, &suffix, false)?;
        }
        let start_index = from
            .or_else(|| start_edge.map(|(index, _, _)| index))
            .unwrap_or(0);
        let end_index = to
            .or_else(|| end_edge.map(|(index, _, _)| index))
            .unwrap_or_else(|| self.blocks().len());
        let mut merged = Vec::with_capacity(self.blocks().len().saturating_add(blocks.len()));
        merged.extend(self.blocks().iter().take(start_index).cloned());
        merged.extend(blocks);
        merged.extend(self.blocks().iter().skip(end_index.saturating_add(usize::from(
            end_edge.is_some(),
        ))).cloned());
        Self::new(self.attrs().clone(), merged, &Limits::default()).map_err(StepError::Limit)
    }

    /// Returns the text block that strictly contains a position, with its content offset.
    fn strict_text_at(&self, pos: Pos) -> Result<Option<(usize, &Arc<Block>, usize)>, StepError> {
        if pos == Pos(self.size().0) || self.boundary(pos).is_some() {
            return Ok(None);
        }
        let Some((index, block)) = self.block_at(pos) else {
            return Ok(None);
        };
        let Some(text) = block.as_textblock() else {
            return Err(StepError::Unsupported {
                operation: Box::from("slice_structural"),
            });
        };
        let start = self
            .block_range(u32::try_from(index).unwrap_or(u32::MAX))
            .map_or(0, |range| range.start.0);
        let local = usize::try_from(pos.0.saturating_sub(start).saturating_sub(1))
            .unwrap_or(usize::MAX);
        let length = usize::try_from(text.len().0).unwrap_or(usize::MAX);
