/// Rejects open depths the model cannot represent.
fn check_open_depth(slice: &Slice) -> Result<(), StepError> {
    if slice.open_start > 1 || slice.open_end > 1 {
        return Err(StepError::Unsupported {
            operation: Box::from("open_slice_depth"),
        });
    }
