//! Inline text runs and text blocks.
#![allow(
    clippy::excessive_nesting,
    reason = "explicit deterministic branch structure"
)]

use alloc::string::String;
use alloc::vec::Vec;

use crate::error::LimitError;
use crate::math::usize_to_u32;
use crate::pos::Size;

use super::attrs::Attrs;
use super::ids::NodeKind;
use super::marks::MarkSet;

/// Maximum bytes in a canonical text run.
pub const MAX_RUN_BYTES: usize = 4096;

/// Payload of an inline atom.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InlineAtom {
    /// Atom node kind.
    pub kind: NodeKind,
    /// Atom attributes.
    pub attrs: Attrs,
}

/// A text run with one mark set.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Run {
    /// UTF-8 text.
    pub text: String,
    /// Marks applied to the whole run.
    pub marks: MarkSet,
}

impl Run {
    /// Creates a run.
    #[must_use]
    pub fn new(text: String, marks: MarkSet) -> Self {
        Self { text, marks }
    }

    /// Returns the byte length.
    #[must_use]
    pub fn len(&self) -> usize {
        self.text.len()
    }

    /// Returns whether the run is empty.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.text.is_empty()
    }
}

/// One inline item.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum InlineItem {
    /// Text run.
    Text(Run),
    /// Atomic inline node.
    Atom(InlineAtom),
}

impl InlineItem {
    /// Returns the item size.
    #[must_use]
    pub fn size(&self) -> u32 {
        match self {
            Self::Text(run) => usize_to_u32(run.text.len()).unwrap_or(u32::MAX),
            Self::Atom(_) => 1,
        }
    }
}

/// A block with inline content.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TextBlock {
    items: Vec<InlineItem>,
    len: Size,
}

impl TextBlock {
    /// Creates a text block, normalizing empty and adjacent runs.
    #[must_use]
    pub fn new(items: Vec<InlineItem>) -> Self {
        if items_are_canonical(&items) {
            let len = items
                .iter()
                .map(InlineItem::size)
                .fold(0_u32, u32::saturating_add);
            return Self {
                items,
                len: Size(len),
            };
        }
        let mut block = Self {
            items: Vec::with_capacity(items.len()),
            len: Size::ZERO,
        };
        for item in items {
            block.push(item);
        }
        block
    }

    /// Creates an empty text block.
    #[must_use]
    pub fn empty() -> Self {
        Self::new(Vec::new())
    }

