            origin,
            group: batch.group,
            add_to_history: batch.add_to_history,
        };
        let report = match batch::run_ops_with(&mut working, &self.schema, &batch.ops, &meta) {
            Ok(_) => {
                let blocks = ops::block_count(&working);
                ImportReport {
                    accepted: true,
                    blocks,
                    accepted_blocks: blocks,
                    version: self.version(),
                    schema: String::from(self.schema.fingerprint()),
                    request_id: None,
                    source: None,
                    destination: None,
                    id_map: Vec::new(),
                    problems: Vec::new(),
                }
            }
            Err(problem) => ImportReport {
                accepted: false,
                blocks: ops::block_count(&self.inner),
                accepted_blocks: 0,
