//! Canonical JSON writer. No intermediate tree and no whitespace.
#![allow(
    clippy::excessive_nesting,
    reason = "canonical writer mirrors the wire grammar"
)]

use core::fmt::{self, Write};

use crate::model::{AttrValue, Attrs, Block, BlockContent, Doc, Fragment, InlineItem, MarkSet};
use crate::schema::{AttrSpec, Schema};

/// Writes a fragment as canonical JSON.
///
/// # Errors
///
/// Propagates formatting failures from the sink.
pub(super) fn write_fragment_into(
    fragment: &Fragment,
    schema: &Schema,
    out: &mut impl Write,
) -> fmt::Result {
    out.write_str("{\"blocks\":")?;
    write_fragment_body_into(fragment, schema, out)?;
    out.write_char('}')
}

/// Writes the `"blocks":[...]` member without the surrounding object.
///
/// # Errors
///
/// Propagates formatting failures from the sink.
pub(super) fn write_fragment_body_into(
    fragment: &Fragment,
    schema: &Schema,
    out: &mut impl Write,
) -> fmt::Result {
    out.write_char('[')?;
    for (index, block) in fragment.blocks().iter().enumerate() {
        if index > 0 {
            out.write_char(',')?;
        }
        write_block(block, schema, out)?;
    }
    out.write_char(']')
}

/// Writes a document as canonical JSON.
///
/// # Errors
///
/// Propagates formatting failures from the sink.
pub fn write_doc_into(doc: &Doc, schema: &Schema, out: &mut impl Write) -> fmt::Result {
    out.write_str("{\"type\":\"doc\"")?;
    write_attrs(doc.attrs(), &schema.doc().attrs, out)?;
    out.write_str(",\"content\":[")?;
    for (index, block) in doc.blocks().iter().enumerate() {
        if index > 0 {
            out.write_char(',')?;
        }
        write_block(block, schema, out)?;
    }
    out.write_str("]}")
}

fn write_block(block: &Block, schema: &Schema, out: &mut impl Write) -> fmt::Result {
    let Some(spec) = schema.node(block.kind()) else {
        return Err(fmt::Error);
    };
    out.write_str("{\"type\":")?;
    write_string(&spec.name, out)?;
    write_attrs(block.attrs(), &spec.attrs, out)?;
    match block.content() {
        BlockContent::Text(text) => {
            out.write_str(",\"content\":")?;
            write_items(text.items(), schema, out)?;
        }
        BlockContent::Blocks(children) => {
            out.write_str(",\"content\":[")?;
            for (index, child) in children.iter().enumerate() {
                if index > 0 {
                    out.write_char(',')?;
                }
                write_block(child, schema, out)?;
            }
            out.write_char(']')?;
        }
        BlockContent::Atom(_) => {}
    }
    out.write_char('}')
}

/// Writes an inline item sequence as a canonical JSON array.
///
/// # Errors
///
/// Propagates formatting failures from the sink and rejects unknown node kinds.
pub(super) fn write_items(
    items: &[InlineItem],
    schema: &Schema,
    out: &mut impl Write,
) -> fmt::Result {
    out.write_char('[')?;
    for (index, item) in items.iter().enumerate() {
        if index > 0 {
            out.write_char(',')?;
        }
        match item {
            InlineItem::Text(run) => {
                out.write_str("{\"type\":\"text\",\"text\":")?;
                write_string(&run.text, out)?;
                write_marks(&run.marks, schema, out)?;
                out.write_char('}')?;
            }
            InlineItem::Atom(atom) => write_inline_atom(atom, schema, out)?,
        }
    }
    out.write_char(']')
}

