/// Document root attributes: presentation, publication metadata, and editorial metadata.
pub(super) fn doc() -> DocSpec {
    DocSpec::new()
        .content("block+")
        .attr(str_attr("lang"))
        .attr(enum_attr("dir", &["ltr", "rtl", "auto"]))
