    }

    /// Builds the accepted report after the working editor committed.
    fn import_applied(&self, outcome: import::ImportOutcome, audit: AuditLabels) -> String {
        let report = ImportReport {
            accepted: true,
            blocks: ops::block_count(&self.inner),
            accepted_blocks: outcome.accepted_blocks,
            version: self.version(),
            schema: String::from(self.schema.fingerprint()),
            request_id: audit.request_id,
            source: audit.source,
            destination: audit.destination,
            id_map: outcome.id_map,
            problems: Vec::new(),
        };
        report.to_json(&self.doc_json(), self.inner.selection())
    }

    /// Builds a rejected import report without mutating the editor.
    fn import_failure(
        &self,
        problem: &ProblemDetails,
        request_id: Option<&str>,
        source: Option<&str>,
        destination: Option<&str>,
    ) -> String {
        let report = ImportReport {
            accepted: false,
            blocks: ops::block_count(&self.inner),
            accepted_blocks: 0,
            version: self.version(),
            schema: String::from(self.schema.fingerprint()),
            request_id: request_id.map(String::from),
            source: source.map(String::from),
            destination: destination.map(String::from),
            id_map: Vec::new(),
            problems: vec![problem.clone()],
        };
        report.to_json(&self.doc_json(), self.inner.selection())
    }
